import{_ as e}from"./chunks/CourseWebArticle.vue_vue_type_style_index_0_lang.8827500c.js";import{u as d}from"./chunks/useSourceFidelity.1de50352.js";import{o as s,c as n,H as o,l as a}from"./chunks/framework.ac6a668e.js";const l='<section data-web-part="0"><div dir="auto" data-markdown-text-style="assistant-message" style="--markdown-link-color: currentColor;" data-web-style="s0"><div data-dil-source-message-id="c9822f68-1d23-4612-b983-f07fead9f804" data-web-style="s1"><div data-web-style="s1"><div hidden="" data-web-style="s2"></div><div style="--puik-portal-zoom: 1;" data-web-style="s1"><div dir="auto" data-d-inline-reveal="" data-d-direction="col" data-dil-message-id="c9822f68-1d23-4612-b983-f07fead9f804" data-web-style="s3"><h1 data-d-text-flow="" data-d-component="title" data-d-size="xl" data-d-weight="semibold" data-web-style="s4">📘 第 05 篇：大语言模型是如何训练出来的？</h1><div data-d-align="center" data-d-component="row" data-d-direction="row" data-d-wrap="wrap" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s5"><div data-color="success" data-size="sm" data-pill="" data-variant="soft" data-d-component="badge" data-d-weight="medium" data-web-style="s6">第 05 / 40 篇</div><p data-d-text-flow="" data-d-component="text" data-d-size="xs" style="color: var(--color-text-secondary);" data-web-style="s7">第一阶段：AI 与大模型基础</p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" style="color: var(--color-text-secondary);" data-web-style="s7"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-d-inline="" style="display: inline-block; vertical-align: calc(0.5cap - 0.5em);" data-web-style="s8" viewBox="0 0 24 24"><path d="M12 4C7.58172 4 4 7.58172 4 12C4 16.4183 7.58172 20 12 20C16.4183 20 20 16.4183 20 12C20 7.58172 16.4183 4 12 4ZM2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22C6.47715 22 2 17.5228 2 12ZM12 6C12.5523 6 13 6.44772 13 7V12C13 12.2652 12.8946 12.5196 12.7071 12.7071L10.2071 15.2071C9.81658 15.5976 9.18342 15.5976 8.79289 15.2071C8.40237 14.8166 8.40237 14.1834 8.79289 13.7929L11 11.5858V7C11 6.44772 11.4477 6 12 6Z" fill="currentColor" data-web-style="s9"></path></svg> 阅读约 12 分钟</p></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">前四篇，我们已经学习了 Token、Embedding、Transformer、Attention 和位置编码。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">但有一个问题还没有解决：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">Transformer 一开始只是一堆数学运算，为什么经过训练之后，它就能够写代码、回答问题，甚至进行推理？</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">这一篇我们将了解大语言模型从随机参数到聊天助手的完整训练过程。</p><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s12">一、模型刚出生时，什么都不会</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s13">假设我们构建一个非常小的语言模型，输入：</p><blockquote data-d-component="blockquote" data-web-style="s14"><p data-d-text-flow="" data-d-component="text" data-web-style="s15">JavaScript 是一种 ______</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s10">训练之前，模型可能给出这样的预测：</p><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s16"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto;" data-web-style="s17"><tbody data-web-style="s18"><tr data-d-component="table-row" data-web-style="s19"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s20"><p data-d-text-flow="" data-d-component="text" data-web-style="s21">候选词</p></th><th data-d-align="end" data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s22"><p data-d-text-flow="" data-d-component="text" data-web-style="s23">预测概率</p></th></tr><tr data-d-component="table-row" data-web-style="s19"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s24"><p data-d-text-flow="" data-d-component="text" data-web-style="s25">水果</p></td><td data-d-align="end" data-d-component="table-cell" data-d-valign="start" data-web-style="s26"><p data-d-text-flow="" data-d-component="text" data-web-style="s27">35%</p></td></tr><tr data-d-component="table-row" data-web-style="s19"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s24"><p data-d-text-flow="" data-d-component="text" data-web-style="s25">汽车</p></td><td data-d-align="end" data-d-component="table-cell" data-d-valign="start" data-web-style="s26"><p data-d-text-flow="" data-d-component="text" data-web-style="s27">25%</p></td></tr><tr data-d-component="table-row" data-web-style="s19"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s24"><p data-d-text-flow="" data-d-component="text" data-web-style="s25">编程</p></td><td data-d-align="end" data-d-component="table-cell" data-d-valign="start" data-web-style="s26"><p data-d-text-flow="" data-d-component="text" data-web-style="s27">20%</p></td></tr><tr data-d-component="table-row" data-web-style="s19"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s24"><p data-d-text-flow="" data-d-component="text" data-web-style="s25">动物</p></td><td data-d-align="end" data-d-component="table-cell" data-d-valign="start" data-web-style="s26"><p data-d-text-flow="" data-d-component="text" data-web-style="s27">20%</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">这些是假设数据。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">模型最初的参数通常经过随机初始化，并不知道 JavaScript 是什么。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">训练的目标就是让模型不断调整参数，使正确 Token 获得更高的预测概率。</p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s28"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">模型训练的核心循环</span></p><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: var(--color-surface-secondary);" data-web-style="s30">输入训练文本</div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s31"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-secondary); font-size: 16px;" data-web-style="s32" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s33"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(37,99,235,0.08); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: rgba(37, 99, 235, 0.08);" data-web-style="s34">Transformer 预测下一个 Token</div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s31"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-secondary); font-size: 16px;" data-web-style="s32" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s33"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: var(--color-surface-secondary);" data-web-style="s30">计算预测误差（Loss）</div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s31"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-secondary); font-size: 16px;" data-web-style="s32" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s33"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(22,163,74,0.08); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: rgba(22, 163, 74, 0.08);" data-web-style="s35">反向传播 + 优化器更新参数</div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s31"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-secondary); font-size: 16px;" data-web-style="s32" viewBox="0 0 24 24"><path d="M3.06956 10.8763C3.6233 6.43564 7.40965 3 12 3C14.2823 3 16.4028 3.85067 18.0118 5.25439V4C18.0118 3.44772 18.4595 3 19.0118 3C19.5641 3 20.0118 3.44772 20.0118 4V8C20.0118 8.55228 19.5641 9 19.0118 9H15C14.4477 9 14 8.55228 14 8C14 7.44772 14.4477 7 15 7H16.9571C15.6756 5.76379 13.9101 5 12 5C8.43107 5 5.48465 7.67174 5.05419 11.1237C4.98585 11.6718 4.48617 12.0607 3.93813 11.9923C3.39009 11.924 3.00122 11.4243 3.06956 10.8763ZM20.0618 12.0077C20.6099 12.076 20.9987 12.5757 20.9304 13.1237C20.3767 17.5644 16.5903 21 12 21C9.72321 21 7.6076 20.1535 5.99998 18.7559V20C5.99998 20.5523 5.55226 21 4.99998 21C4.44769 21 3.99998 20.5523 3.99998 20V16C3.99998 15.4477 4.44769 15 4.99998 15H8.99998C9.55226 15 9.99998 15.4477 9.99998 16C9.99998 16.5523 9.55226 17 8.99998 17H7.04283C8.32432 18.2362 10.0899 19 12 19C15.5689 19 18.5153 16.3283 18.9458 12.8763C19.0141 12.3282 19.5138 11.9393 20.0618 12.0077Z" fill="currentColor" data-web-style="s33"></path></svg></div><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-d-text-align="center" data-web-style="s36">重复大量训练步骤，模型逐步学习数据中的规律</span></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s12">二、Loss：模型如何知道自己错了？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s13">训练语言模型常用的损失函数是交叉熵（Cross-Entropy）。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">假设正确答案是「编程」，模型给它的概率只有 0.2。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">那么对应的损失可以写成：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s37"><span data-web-style="s38"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mo>−</mo><mi>ln</mi><mo>⁡</mo><mo stretchy="false">(</mo><mi>P</mi><mo stretchy="false">(</mo><mtext>编程</mtext><mo stretchy="false">)</mo><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">L=-\\ln(P(\\text{编程}))</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord">−</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mop">ln</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right: 0.1389em;">P</span><span class="mopen">(</span><span class="mord text"><span class="mord cjk_fallback">编程</span></span><span class="mclose">))</span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">也就是：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s37"><span data-web-style="s38"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mo>−</mo><mi>ln</mi><mo>⁡</mo><mo stretchy="false">(</mo><mn>0.2</mn><mo stretchy="false">)</mo><mo>≈</mo><mn>1.609</mn></mrow><annotation encoding="application/x-tex">L=-\\ln(0.2)\\approx1.609</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord">−</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mop">ln</span><span class="mopen">(</span><span class="mord">0.2</span><span class="mclose">)</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">1.609</span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">如果训练后，模型给正确答案的概率提高到 0.9：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s37"><span data-web-style="s38"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mo>−</mo><mi>ln</mi><mo>⁡</mo><mo stretchy="false">(</mo><mn>0.9</mn><mo stretchy="false">)</mo><mo>≈</mo><mn>0.105</mn></mrow><annotation encoding="application/x-tex">L=-\\ln(0.9)\\approx0.105</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord">−</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mop">ln</span><span class="mopen">(</span><span class="mord">0.9</span><span class="mclose">)</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">0.105</span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">Loss 就明显降低了。</p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 3);" data-web-style="s39" data-web-lab="loss" data-web-lab-id="loss"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">交互实验：正确答案概率与 Loss</span></p><div data-d-align="center" data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s40"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s41">正确 Token 的预测概率</p><p data-d-text-flow="" data-d-component="text" data-web-style="s42"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11" data-web-range-label="0" data-web-format="{value}%">20%</span></p></div><input type="range" min="1" max="100" value="20" step="1" aria-label="教程交互参数 1" data-web-range="0" data-web-initial="20" style="display:block;width:100%;min-width:0;accent-color:var(--vp-c-brand-1);cursor:pointer"><div data-d-align="center" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: var(--color-surface-secondary); gap: calc(var(--spacing, 0.25rem) * 1);" data-web-style="s47"><p data-d-text-flow="" data-d-component="text" data-d-size="xs" style="color: var(--color-text-secondary);" data-web-style="s7">交叉熵损失</p><h1 data-d-text-flow="" data-d-component="title" data-d-size="2xl" data-d-weight="semibold" data-d-tabular-nums="true" data-web-style="s48" data-web-output="loss">1.609</h1><p data-d-text-flow="" data-d-component="text" data-d-size="xs" style="color: var(--color-text-secondary);" data-web-style="s7" data-web-output="loss-description">正确答案概率较低，损失较高</p></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">注意：Loss 下降不等于模型已经学会判断事实真假。</span> 它主要说明模型在相应训练目标上的预测表现改善了。</p><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s12">三、反向传播：模型怎样修改自己的参数？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s13">模型内部可能有数十亿甚至更多参数。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">训练时会计算 Loss 对各个参数的梯度，再由优化器决定如何更新参数。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">最简单的梯度下降形式是：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s37"><span data-web-style="s38"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>θ</mi><mtext>new</mtext></msub><mo>=</mo><msub><mi>θ</mi><mtext>old</mtext></msub><mo>−</mo><mi>η</mi><msub><mi mathvariant="normal">∇</mi><mi>θ</mi></msub><mi>L</mi></mrow><annotation encoding="application/x-tex">\\theta_{\\text{new}}=\\theta_{\\text{old}}-\\eta\\nabla_\\theta L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8444em; vertical-align: -0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.1514em;"><span style="top: -2.55em; margin-left: -0.0278em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">new</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.8444em; vertical-align: -0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span style="top: -2.55em; margin-left: -0.0278em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">old</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.8778em; vertical-align: -0.1944em;"></span><span class="mord mathnormal" style="margin-right: 0.0359em;">η</span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span style="top: -2.55em; margin-left: 0em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right: 0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal">L</span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">其中：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0); gap: calc(var(--spacing, 0.25rem) * 0);" data-web-style="s49"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s50"><div data-web-style="s51"><div data-d-list-item-content="" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s15"><span data-d-component="math" dir="ltr" data-web-style="s53"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>θ</mi></mrow><annotation encoding="application/x-tex">\\theta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6944em;"></span><span class="mord mathnormal" style="margin-right: 0.0278em;">θ</span></span></span></span></span>：模型参数</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s50"><div data-web-style="s51"><div data-d-list-item-content="" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s15"><span data-d-component="math" dir="ltr" data-web-style="s53"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>η</mi></mrow><annotation encoding="application/x-tex">\\eta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.625em; vertical-align: -0.1944em;"></span><span class="mord mathnormal" style="margin-right: 0.0359em;">η</span></span></span></span></span>：学习率</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s50"><div data-web-style="s51"><div data-d-list-item-content="" data-web-style="s52"><p data-d-text-flow="" data-d-component="text" data-web-style="s15"><span data-d-component="math" dir="ltr" data-web-style="s53"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi mathvariant="normal">∇</mi><mi>θ</mi></msub><mi>L</mi></mrow><annotation encoding="application/x-tex">\\nabla_\\theta L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span style="top: -2.55em; margin-left: 0em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right: 0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal">L</span></span></span></span></span>：损失函数对参数的梯度</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s10">可以把它理解为：模型根据当前错误，计算应该朝哪个方向调整参数，以期降低后续预测误差。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">实际的大模型训练通常使用 AdamW 等优化器，而不是简单的梯度下降。</p><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s12">四、从语言模型到 ChatGPT，需要哪些训练阶段？</h2><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s28"><div data-d-align="start" data-d-component="row" data-d-direction="row" style="gap: calc(var(--spacing, 0.25rem) * 3);" data-web-style="s54"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-tertiary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 2); padding-block: calc(var(--spacing, 0.25rem) * 2); padding-inline: calc(var(--spacing, 0.25rem) * 2); background-color: var(--color-surface-tertiary);" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-d-weight="medium" data-d-tabular-nums="true" data-web-style="s56">1</p></div><div data-d-component="box" data-d-direction="col" style="flex: 1 1 0%; gap: calc(var(--spacing, 0.25rem) * 1);" data-web-style="s57"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">阶段 1：预训练（Pretraining）</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" style="color: var(--color-text-secondary);" data-web-style="s58">通过大规模文本和代码数据学习语言与知识规律</p></div></div><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--w-box-gutter-inline-end: 0px; --w-box-gutter-inline-start: 13px; padding-inline-start: 13px;" data-web-style="s59"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-tertiary); font-size: 16px;" data-web-style="s60" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s61"></path></svg></div><div data-d-align="start" data-d-component="row" data-d-direction="row" style="gap: calc(var(--spacing, 0.25rem) * 3);" data-web-style="s54"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-tertiary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 2); padding-block: calc(var(--spacing, 0.25rem) * 2); padding-inline: calc(var(--spacing, 0.25rem) * 2); background-color: var(--color-surface-tertiary);" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-d-weight="medium" data-d-tabular-nums="true" data-web-style="s56">2</p></div><div data-d-component="box" data-d-direction="col" style="flex: 1 1 0%; gap: calc(var(--spacing, 0.25rem) * 1);" data-web-style="s57"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">阶段 2：监督微调（SFT）</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" style="color: var(--color-text-secondary);" data-web-style="s58">通过高质量指令与回答样本学习如何遵循用户要求</p></div></div><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--w-box-gutter-inline-end: 0px; --w-box-gutter-inline-start: 13px; padding-inline-start: 13px;" data-web-style="s59"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-tertiary); font-size: 16px;" data-web-style="s60" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s61"></path></svg></div><div data-d-align="start" data-d-component="row" data-d-direction="row" style="gap: calc(var(--spacing, 0.25rem) * 3);" data-web-style="s54"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-tertiary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 2); padding-block: calc(var(--spacing, 0.25rem) * 2); padding-inline: calc(var(--spacing, 0.25rem) * 2); background-color: var(--color-surface-tertiary);" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-d-weight="medium" data-d-tabular-nums="true" data-web-style="s56">3</p></div><div data-d-component="box" data-d-direction="col" style="flex: 1 1 0%; gap: calc(var(--spacing, 0.25rem) * 1);" data-web-style="s57"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">阶段 3：偏好对齐</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" style="color: var(--color-text-secondary);" data-web-style="s58">通过 RLHF、DPO 等方法改善回答的有用性与行为表现</p></div></div><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--w-box-gutter-inline-end: 0px; --w-box-gutter-inline-start: 13px; padding-inline-start: 13px;" data-web-style="s59"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-tertiary); font-size: 16px;" data-web-style="s60" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s61"></path></svg></div><div data-d-align="start" data-d-component="row" data-d-direction="row" style="gap: calc(var(--spacing, 0.25rem) * 3);" data-web-style="s54"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-tertiary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 2); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 2); padding-block: calc(var(--spacing, 0.25rem) * 2); padding-inline: calc(var(--spacing, 0.25rem) * 2); background-color: var(--color-surface-tertiary);" data-web-style="s55"><p data-d-text-flow="" data-d-component="text" data-d-weight="medium" data-d-tabular-nums="true" data-web-style="s56">4</p></div><div data-d-component="box" data-d-direction="col" style="flex: 1 1 0%; gap: calc(var(--spacing, 0.25rem) * 1);" data-web-style="s57"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">阶段 4：评估与迭代</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" style="color: var(--color-text-secondary);" data-web-style="s58">测试正确性、安全性、指令遵循与真实任务表现</p></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">不同模型的实际训练流程可能不同，不一定严格采用这四个阶段，也可能引入额外的强化学习、蒸馏或其他训练方法。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s62">预训练与 SFT 有什么区别？</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s13">预训练时，模型主要学习：</p><blockquote data-d-component="blockquote" data-web-style="s14"><p data-d-text-flow="" data-d-component="text" data-web-style="s15">给定前面的文本，后面可能是什么？</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s10">SFT 时，模型进一步学习：</p><blockquote data-d-component="blockquote" data-web-style="s14"><p data-d-text-flow="" data-d-component="text" data-web-style="s15">用户提出这个问题时，应该如何按照指令回答？</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s10">因此，<span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">语言能力与聊天助手的指令遵循能力并不是完全相同的东西</span>。</p><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s12">五、工程师需要自己训练大模型吗？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s13">对于绝大多数 AI 聊天机器人项目，答案是：<span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">不需要</span>。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">你可以直接调用现成的模型 API，把主要精力放在会话管理、RAG、工具调用、权限、安全和用户体验上。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">只有当现有模型不能很好满足特定领域需求，并且已经有合适的数据与评估体系时，才需要认真考虑微调。</p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s63"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s12">六、课后测验</h2><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 3);" data-web-style="s39"><div data-d-component="box" data-d-direction="col" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s64"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">1. 预训练自回归语言模型的主要目标是什么？</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="Options" data-d-component="radio-group" style="outline: none;" data-web-style="s65" data-web-question="0"><div data-d-component="radio" data-web-style="s66"><label for="0-_r_5l0_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-0" value="0" id="0-_r_5l0_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>预测下一个 Token</label></div><div data-d-component="radio" data-web-style="s66"><label for="1-_r_5l2_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-0" value="1" id="1-_r_5l2_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>验证所有事实是否正确</label></div><div data-d-component="radio" data-web-style="s66"><label for="2-_r_5l4_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-0" value="2" id="2-_r_5l4_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>保存用户聊天记录</label></div></div></div><div data-d-component="divider" style="--divider-color: var(--color-border-subtle); --divider-size: 1px;" data-web-style="s70"></div><div data-d-component="box" data-d-direction="col" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s64"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">2. 正确 Token 的预测概率提高，负对数损失通常如何变化？</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="Options" data-d-component="radio-group" style="outline: none;" data-web-style="s65" data-web-question="1"><div data-d-component="radio" data-web-style="s66"><label for="0-_r_5l7_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-1" value="0" id="0-_r_5l7_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>增加</label></div><div data-d-component="radio" data-web-style="s66"><label for="1-_r_5l9_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-1" value="1" id="1-_r_5l9_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>降低</label></div><div data-d-component="radio" data-web-style="s66"><label for="2-_r_5lb_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-1" value="2" id="2-_r_5lb_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>不变</label></div></div></div><div data-d-component="divider" style="--divider-color: var(--color-border-subtle); --divider-size: 1px;" data-web-style="s70"></div><div data-d-component="box" data-d-direction="col" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s64"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">3. SFT 的主要作用是什么？</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="Options" data-d-component="radio-group" style="outline: none;" data-web-style="s65" data-web-question="2"><div data-d-component="radio" data-web-style="s66"><label for="0-_r_5le_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-2" value="0" id="0-_r_5le_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>提升显卡性能</label></div><div data-d-component="radio" data-web-style="s66"><label for="1-_r_5lg_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-2" value="1" id="1-_r_5lg_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>让模型更好地遵循指令</label></div><div data-d-component="radio" data-web-style="s66"><label for="2-_r_5li_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-2" value="2" id="2-_r_5li_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>直接更新企业知识库</label></div></div></div><div data-d-component="divider" style="--divider-color: var(--color-border-subtle); --divider-size: 1px;" data-web-style="s70"></div><div data-d-component="box" data-d-direction="col" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s64"><p data-d-text-flow="" data-d-component="text" data-web-style="s29"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">4. 企业知识库内容经常更新，应优先考虑什么方案？</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="Options" data-d-component="radio-group" style="outline: none;" data-web-style="s65" data-web-question="3"><div data-d-component="radio" data-web-style="s66"><label for="0-_r_5ll_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-3" value="0" id="0-_r_5ll_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>从零训练模型</label></div><div data-d-component="radio" data-web-style="s66"><label for="1-_r_5ln_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-3" value="1" id="1-_r_5ln_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>只增加 Temperature</label></div><div data-d-component="radio" data-web-style="s66"><label for="2-_r_5lp_" data-web-style="s67"><div data-web-style="s68"><input type="radio" name="web-lesson-5-question-3" value="2" id="2-_r_5lp_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>使用 RAG 检索最新文档</label></div></div></div><div data-d-component="row" data-d-direction="row" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s71"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="flex: 1 1 0%;" data-web-style="s51"><button type="button" data-color="primary" data-variant="solid" data-pill="" data-size="lg" data-block="" data-d-component="button" data-d-block="" data-web-style="s72" data-web-action="submit-quiz"><span data-web-style="s73">提交评分</span></button></div><button type="button" data-color="secondary" data-variant="outline" data-pill="" data-size="lg" data-d-component="button" data-web-style="s74" data-web-action="reset-quiz"><span data-web-style="s75">重新作答</span></button></div></div><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s63"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s12">第 05 篇学习进度</h2><div data-d-align="center" data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s76"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" style="color: var(--color-text-secondary);" data-web-style="s58">5 / 40 篇</p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" data-web-style="s77">12.5%</p></div><div data-d-auto-spacing="" data-d-clip="true" data-d-component="box" data-d-direction="col" data-d-has-height="" style="--smoothing-background-color: var(--color-surface-tertiary); border-radius: 9999px; background-color: var(--color-surface-tertiary); flex-shrink: 0; height: 7px;" data-web-style="s78"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" data-d-has-width="" data-d-has-height="" style="--smoothing-background-color: rgba(22,163,74,0.85); border-radius: 9999px; background-color: rgba(22, 163, 74, 0.85); flex-shrink: 0; height: 100%; width: 12.5%;" data-web-style="s79"></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">GitHub 发布状态：</span> 我已确认仓库中的前四篇教程及课程目录，但这次尝试写入第 05 篇时未能完成提交，因此目前不能声称已发布到 GitHub。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">下一篇将是 <span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">第 06 篇：《模型推理：ChatGPT 为什么能一个 Token 一个 Token 地生成回答？》</span>，重点学习 Prefill、Decode、KV Cache、Temperature、Top-p 和推理性能。</p></div></div></div></div></div></section>',i=5,r=[{answer:0,explanation:"自回归预训练以预测下一个 Token 为核心目标。"},{answer:1,explanation:"负对数损失为 −ln(p)，正确 Token 的概率越高，损失越低。"},{answer:1,explanation:"SFT 使用指令与示范回答，帮助模型学习遵循指令。"},{answer:2,explanation:"RAG 可以检索最新文档，适合持续更新的企业知识库。"}],t={chapter:i,questions:r};const y=JSON.parse('{"title":"05 · 大语言模型是如何训练出来的？","description":"","frontmatter":{"title":"05 · 大语言模型是如何训练出来的？","outline":"deep","readingTime":"12","courseMeta":false},"headers":[],"relativePath":"guide/ai/chatbot-course/05-llm-training.md","filePath":"guide/ai/chatbot-course/05-llm-training.md","lastUpdated":1793116094000}'),c={name:"guide/ai/chatbot-course/05-llm-training.md"},x=Object.assign(c,{setup(p){return d(5),(m,b)=>(s(),n("div",null,[o(e,{source:a(l),chapter:a(t).chapter,questions:a(t).questions},null,8,["source","chapter","questions"])]))}});export{y as __pageData,x as default};
